import socket

def scan(host, ports):
    for port in ports:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(0.5)
        try:
            s.connect((host, port))
            print(f'[+] Port {port} is OPEN')
        except:
            pass
        finally:
            s.close()

if __name__ == '__main__':
    target = input('Enter Target IP: ')
    scan(target, [21, 22, 80, 443, 8080])

