const crypto = require('crypto');

function crackHash(targetHash, wordlist) {
    for (let word of wordlist) {
        const hash = crypto.createHash('md5').update(word).digest('hex');
        if (hash === targetHash) {
            console.log(`[+] Password Found: ${word}`);
            return;
        }
    }
    console.log('[-] Not found');
}

crackHash('5d41402abc4b2a76b9719d911017c592', ['admin', '123456', 'hello']);

